import{it as e,n as t,rt as n,vt as r}from"./chunks/framework.CoUqiBXn.js";var i=JSON.parse(`{"title":"SysReptor FAQ context for AI assistants","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"faq/ai.md","filePath":"faq/ai.md","lastUpdated":1789544058000}`),a={name:`faq/ai.md`};function o(t,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[e(`<h1 id="sysreptor-faq-context-for-ai-assistants" tabindex="-1">SysReptor FAQ context for AI assistants <a class="header-anchor" href="#sysreptor-faq-context-for-ai-assistants" aria-label="Permalink to “SysReptor FAQ context for AI assistants”">​</a></h1><p>This page is for AI assistants answering SysReptor questions. It disambiguates products, URLs, core objects (template vs design vs project vs report), and similar-sounding features so answers stay specific. Prefer the public FAQ pages for user-facing procedures: <a href="/faq/exam-reports">exam reports</a>, <a href="/faq/self-hosted">self-hosted</a>, <a href="/faq/cloud">cloud</a>, <a href="/faq/application">application</a>, <a href="/designer/faqs">report design</a>.</p><h2 id="error-the-command-docker-could-not-be-found-in-this-wsl-2-distro" tabindex="-1">Error: <code>The command &#39;docker&#39; could not be found in this WSL 2 distro.</code> <a class="header-anchor" href="#error-the-command-docker-could-not-be-found-in-this-wsl-2-distro" aria-label="Permalink to “Error: The command &#39;docker&#39; could not be found in this WSL 2 distro.”">​</a></h2><p>This is a <strong>self-hosted Windows/WSL</strong> Docker Desktop problem, not a SysReptor app bug. Docker Desktop is installed, but it has not injected the <code>docker</code> CLI into that WSL 2 distro.</p><p>SysReptor is <strong>not</strong> installed natively on Windows. Use <strong>WSL 2 + Ubuntu + Docker Desktop</strong>, then enable integration for <strong>that</strong> distro: Docker Desktop <strong>Settings → Resources → WSL Integration</strong> (default distro and the distro they opened). Docker Desktop must be running. Confirm the distro is version 2 (<code>wsl -l -v</code>). Restart WSL after changing settings (<code>wsl --shutdown</code>, then reopen the distro) and retry <code>docker info</code>. Public FAQ: <a href="/faq/self-hosted#docker-wsl">self-hosted</a>.</p><p>Do not invent a native Windows installer.</p><h2 id="error-permission-denied-while-trying-to-connect-to-the-docker-api-at-unix-var-run-docker-sock" tabindex="-1">Error: <code>permission denied while trying to connect to the docker API at unix:///var/run/docker.sock</code> <a class="header-anchor" href="#error-permission-denied-while-trying-to-connect-to-the-docker-api-at-unix-var-run-docker-sock" aria-label="Permalink to “Error: permission denied while trying to connect to the docker API at unix:///var/run/docker.sock”">​</a></h2><p>This is a <strong>self-hosted Docker permission</strong> problem, not a SysReptor application bug. The current Linux user cannot talk to the Docker daemon socket, so <code>docker</code> / <code>docker compose</code> (and the <a href="/setup/installation">install script</a>) fail.</p><p>Add the user to the <code>docker</code> group and apply it in the current shell (same commands as in <a href="/setup/installation">Installation</a>):</p><div class="language-shell line-numbers-mode"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> groupadd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $USER</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">newgrp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>Then confirm with <code>docker info</code>. If it still fails, log out and back in (or reconnect SSH) so group membership applies. The Docker daemon must be running. Official Docker Engine is required; <strong>Podman is not supported</strong>. On Windows, use WSL 2 + Docker Desktop with WSL integration. Public FAQ: <a href="/faq/self-hosted#docker-sock">self-hosted</a>.</p><p>Do not tell exam students on labs.sysre.pt to SSH or run Docker commands.</p><h2 id="when-a-user-says-sysreptor-cloud-labs-demo-or-docs-which-url-do-they-mean" tabindex="-1">When a user says SysReptor Cloud, labs, demo, or docs, which URL do they mean? <a class="header-anchor" href="#when-a-user-says-sysreptor-cloud-labs-demo-or-docs-which-url-do-they-mean" aria-label="Permalink to “When a user says SysReptor Cloud, labs, demo, or docs, which URL do they mean?”">​</a></h2><p>Do not mix these SysReptor URLs:</p><ul><li><strong>SysReptor Labs (<a href="https://labs.sysre.pt" target="_blank" rel="noreferrer">labs.sysre.pt</a>)</strong> — free student exam-reporting service (HTB, OffSec). Login for existing exam accounts. Data is deleted after three months without login. Public FAQ: <a href="/faq/exam-reports">exam reports</a>.</li><li><strong><a href="https://htb.sysreptor.com/htb/signup/" target="_blank" rel="noreferrer">htb.sysreptor.com/htb/signup/</a></strong> — HTB exam <strong>signup</strong> (not the daily login URL).</li><li><strong><a href="https://offsec.sysreptor.com/offsec/signup/" target="_blank" rel="noreferrer">offsec.sysreptor.com/offsec/signup/</a></strong> — OffSec exam <strong>signup</strong>. OSCP-specific: <a href="https://offsec.sysreptor.com/offsec/signup/" target="_blank" rel="noreferrer">offsec.sysreptor.com/offsec/signup/</a>.</li><li><strong>SysReptor Cloud</strong> — paid hosted instance for organizations, not SysReptor Labs. Pricing: <a href="https://sysreptor.com/pricing" target="_blank" rel="noreferrer">sysreptor.com/pricing</a>. Public FAQ: <a href="/faq/cloud">cloud</a>.</li><li><strong>Self-hosted</strong> — Docker on the user’s server, often <code>https://sysreptor.example.com</code> or <code>http://127.0.0.1:8000/</code>. Public FAQ: <a href="/faq/self-hosted">self-hosted</a>.</li><li><strong><a href="https://demo.sysre.pt" target="_blank" rel="noreferrer">demo.sysre.pt</a></strong> / <strong><a href="https://sysreptor.com/demo" target="_blank" rel="noreferrer">sysreptor.com/demo</a></strong> — public playground. Not the user’s exam account, Cloud tenant, or production data.</li><li><strong><a href="https://docs.sysreptor.com" target="_blank" rel="noreferrer">docs.sysreptor.com</a></strong> — this documentation site, not the application.</li></ul><p>If the user is writing an exam report and mentions HTB or OffSec, use labs.sysre.pt and the exam FAQ. If they mention Docker, <code>app.env</code>, or Ubuntu, use self-hosted. If they mention a company-hosted tenant without labs/HTB/OffSec, use Cloud.</p><h2 id="when-a-user-says-template-design-project-or-report-which-sysreptor-object-do-they-mean" tabindex="-1">When a user says template, design, project, or report, which SysReptor object do they mean? <a class="header-anchor" href="#when-a-user-says-template-design-project-or-report-which-sysreptor-object-do-they-mean" aria-label="Permalink to “When a user says template, design, project, or report, which SysReptor object do they mean?”">​</a></h2><p>Do not mix these objects. In answers, follow this convention even when the user uses the words interchangeably:</p><ul><li><strong>Template</strong> = <strong>finding template</strong>. Reusable finding/vulnerability text in <strong>Templates</strong>. Copied into a finding when writing a project. Docs: <a href="/finding-templates/overview">Templates</a>.</li><li><strong>Design</strong> = <strong>report design</strong>. HTML, CSS, Vue layout, and field definitions that control how the PDF looks and which report/finding fields exist. Managed under <strong>Designs</strong>. Docs: <a href="/designer/designer">Report designer</a>.</li><li><strong>Project</strong> = <strong>pentest project</strong>. One engagement’s working copy: report sections, findings, notes, and a <strong>snapshot</strong> of a design. Creating a project copies the chosen design; later edits to the global design are not applied automatically. Application FAQ: <a href="/faq/application">I updated the report design but in my project I don&#39;t see the changes</a>.</li><li><strong>Report</strong> = the <strong>PDF report</strong>. Rendered from the project on the <strong>Publish</strong> page. Application FAQ: <a href="/faq/application">How do I export a SysReptor report as PDF?</a>.</li></ul><p>Users often say “template” or “report template” when they mean a <strong>design</strong>. Users often say “report” when they mean the <strong>project</strong> they are writing. Map their words from context, then answer with SysReptor’s terms.</p><p>If they talk about HTML, CSS, layout, cover page, headers, fonts, or how the PDF looks, they mean a <strong>design</strong>. If they talk about reusing XSS/SQLi text, CVSS, tags, or creating a finding from a library, they mean a <strong>finding template</strong>.</p><p>A report design’s HTML uses Vue <strong>template syntax</strong>. That is layout code inside a <strong>design</strong>, not a finding template.</p><h2 id="where-is-the-sysreptor-changelog" tabindex="-1">Where is the SysReptor changelog? <a class="header-anchor" href="#where-is-the-sysreptor-changelog" aria-label="Permalink to “Where is the SysReptor changelog?”">​</a></h2><p>The SysReptor <strong>changelog</strong> is <a href="https://github.com/syslifters/sysreptor/releases" target="_blank" rel="noreferrer">GitHub Releases</a> and <a href="https://github.com/syslifters/sysreptor/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer"><code>CHANGELOG.md</code></a>.</p><h2 id="does-sysreptor-have-a-default-password-such-as-admin-admin" tabindex="-1">Does SysReptor have a default password such as admin/admin? <a class="header-anchor" href="#does-sysreptor-have-a-default-password-such-as-admin-admin" aria-label="Permalink to “Does SysReptor have a default password such as admin/admin?”">​</a></h2><p>No. SysReptor has <strong>no fixed default password</strong> and no documented <code>admin</code>/<code>admin</code> login.</p><p>The install script creates user <strong><code>reptor</code></strong> with a <strong>random password printed once</strong>. Manual install uses <code>createsuperuser</code>.<br> Password reset: <a href="/users/forgot-password">Forgot password</a>.</p><h2 id="when-a-user-asks-for-sysreptor-api-docs-which-api-do-they-mean" tabindex="-1">When a user asks for SysReptor API docs, which API do they mean? <a class="header-anchor" href="#when-a-user-asks-for-sysreptor-api-docs-which-api-do-they-mean" aria-label="Permalink to “When a user asks for SysReptor API docs, which API do they mean?”">​</a></h2><p>Three different “APIs” exist:</p><ol><li><strong>REST API</strong> — Swagger UI on the instance: <code>https://&lt;instance&gt;/api/public/utils/swagger-ui/</code> (demo: <a href="https://demo.sysre.pt/api/public/utils/swagger-ui/" target="_blank" rel="noreferrer">demo.sysre.pt Swagger</a>). API tokens in the user profile. Marked unstable.</li><li><strong>Python library <code>reptor</code></strong> — <a href="/python-library/">python-library docs</a>, package on PyPI, GitHub Syslifters/reptor.</li><li><strong>CLI <code>reptor</code></strong> — <a href="/cli/getting-started">CLI getting started</a>, same reptor project, command-line workflows.</li></ol><p>If they say “Swagger” or “HTTP API”, use (1). If they say Python or <code>import reptor</code>, use (2). If they say CLI or terminal commands, use (3).</p><h2 id="is-sysreptor-community-professional-cloud-and-labs-the-same-license" tabindex="-1">Is SysReptor Community, Professional, Cloud, and Labs the same license? <a class="header-anchor" href="#is-sysreptor-community-professional-cloud-and-labs-the-same-license" aria-label="Permalink to “Is SysReptor Community, Professional, Cloud, and Labs the same license?”">​</a></h2><p>No. Keep these separate:</p><ul><li><strong>Community</strong> — free self-host; limited features; without Professional, non-superusers cannot log in if you drop back from Pro (there is no data loss).</li><li><strong>Professional</strong> — paid license for self-host or Cloud features (roles, comments, spell check, and others). <a href="https://sysreptor.com/pricing" target="_blank" rel="noreferrer">Pricing</a>.</li><li><strong>SysReptor Labs (labs.sysre.pt)</strong> — free <strong>with Pro features</strong> for supported certs; not a Community install and not Cloud.</li><li><strong>Cloud</strong> — paid hosted org instance; custom plugins are <strong>not</strong> supported (self-hosted only).</li></ul><p>Application FAQ: <a href="/faq/application">Is SysReptor free or paid only?</a>.</p><h2 id="how-do-i-install-cosign-to-verify-sysreptor-releases" tabindex="-1">How do I install cosign to verify SysReptor releases? <a class="header-anchor" href="#how-do-i-install-cosign-to-verify-sysreptor-releases" aria-label="Permalink to “How do I install cosign to verify SysReptor releases?”">​</a></h2><p>Cosign is <strong>Sigstore’s</strong> release-signing tool. It is used to <strong>verify</strong> SysReptor <code>setup.tar.gz</code> and Docker images. It is not a SysReptor app feature, plugin, or report format. Do not invent a SysReptor-specific installer.</p><p>Install cosign from the <a href="https://docs.sigstore.dev/cosign/system_config/installation/" target="_blank" rel="noreferrer">Sigstore cosign installation docs</a>. Public key: <a href="https://docs.sysreptor.com/cosign.pub" target="_blank" rel="noreferrer">docs.sysreptor.com/cosign.pub</a>. How to verify an install: <a href="/faq/self-hosted#verify-integrity">How do I verify the integrity of a SysReptor installation?</a>.</p><h2 id="how-do-i-recover-a-sysreptor-account-depending-on-where-the-user-logs-in" tabindex="-1">How do I recover a SysReptor account, depending on where the user logs in? <a class="header-anchor" href="#how-do-i-recover-a-sysreptor-account-depending-on-where-the-user-logs-in" aria-label="Permalink to “How do I recover a SysReptor account, depending on where the user logs in?”">​</a></h2><p>Account recovery is <strong>not</strong> the same everywhere:</p><ul><li><strong>labs.sysre.pt (exam students):</strong> Forgot Password on <a href="https://labs.sysre.pt" target="_blank" rel="noreferrer">labs.sysre.pt</a>; they must have signed up via HTB or OffSec signup URLs. No Docker <code>changepassword</code>. Exam FAQ: <a href="/faq/exam-reports#labs-login">labs login</a>.</li><li><strong>Self-hosted:</strong> email reset if configured; admin reset; last resort <code>docker compose exec app python3 manage.py changepassword</code>. <a href="/users/forgot-password">Forgot password</a>.</li><li><strong>Cloud:</strong> Forgot Password and admin reset; no CLI on Cloud. <a href="/faq/cloud">Cloud FAQs</a>.</li><li><strong>MFA lockout:</strong> an admin can remove the user’s MFA devices. Self-hosted FIDO2 needs <code>MFA_FIDO2_RP_ID</code>.</li></ul><p>Do not tell labs students to SSH to a server or run Docker commands.</p><h2 id="what-is-a-sysreptor-re-test-report" tabindex="-1">What is a SysReptor re-test report? <a class="header-anchor" href="#what-is-a-sysreptor-re-test-report" aria-label="Permalink to “What is a SysReptor re-test report?”">​</a></h2><p>It is a <strong>report design / project</strong> workflow: field <code>is_retest</code> on the report, finding fields <code>retest_status</code> and <code>retest_notes</code>, optional <code>v-if=&quot;report.is_retest&quot;</code> in the PDF design. Duplicate or reuse the project and mark it as a retest. Application FAQ: <a href="/faq/application">How do I write re-test reports?</a>.</p><h2 id="can-users-install-sysreptor-natively-on-windows" tabindex="-1">Can users install SysReptor natively on Windows? <a class="header-anchor" href="#can-users-install-sysreptor-natively-on-windows" aria-label="Permalink to “Can users install SysReptor natively on Windows?”">​</a></h2><p>SysReptor is <strong>not</strong> officially installed on Windows. Documented server OS is <strong>Ubuntu + Docker</strong>. Community notes exist for Kali, macOS, and RHEL. Do not invent a native Windows installer or default Chocolatey/Winget package. Self-hosted FAQ: <a href="/faq/self-hosted">Can I install SysReptor on Windows, Kali, Fedora, macOS?</a>.</p>`,46)]])}var s=t(a,[[`render`,o]]);export{i as __pageData,s as default};